public class OrderMetrics
{
    private readonly Counter<long> _ordersCreated;
    private readonly Counter<long> _orderValue;

    public OrderMetrics(IMeterFactory meterFactory)
    {
        var meter = meterFactory.Create("Quotient.Orders");
        _ordersCreated = meter.CreateCounter<long>("orders.created");
        _orderValue = meter.CreateCounter<long>("orders.value.total");
    }

    public void RecordOrderCreated(decimal amount)
    {
        _ordersCreated.Add(1);
        _orderValue.Add((long)(amount * 100));
    }
}

